import csv,collections,ast,datetime
R=list(csv.DictReader(open('/app/dataset/timesheet.csv')))
E={r['PESEL']:r for r in csv.DictReader(open('/app/dataset/employees.csv'))}
T={int(r['task_id']):float(r['pay_per_completion']) for r in csv.DictReader(open('/app/dataset/tasks.csv'))}
for p in ['68011810139','68011910138','96102016751','16102016795']:
 print('\nEMPLOYEE',p)
 for r in sorted([r for r in R if r['employee_id']==p],key=lambda r:(r['date'],r['id'])):
  print(r)
print('\nROWS FIRST DATE')
for r in sorted([r for r in R if r['date']=='2025-03-04'],key=lambda r:r['employee_id']):print(r)
print('\nINVALID DATE ROWS')
for r in R:
 try:datetime.date.fromisoformat(r['date'])
 except: print(r)
print('\nTASK UNKNOWN')
for r in R:
 tasks=ast.literal_eval(r['performed_tasks'])
 unknown=[t for t in tasks if t not in T]
 if unknown:print(r,'unknown',unknown)
print('\nBONUS MISMATCH')
bad=[]
for r in R:
 total=sum(T.get(t,0) for t in ast.literal_eval(r['performed_tasks']))
 if total!=float(r['bonus']): bad.append((r,total))
print('count',len(bad))
for r,total in bad:print(r,'expected_bonus',total)
PY","max_output_tokens":14000}));

