T={int(r['task_id']):float(r['pay_per_completion']) for r in csv.DictReader(open('/app/dataset/tasks.csv'))}
c=collections.Counter(tuple((k,v) for k,v in r.items() if k!='id') for r in R)
print('duplicate groups',sum(n>1 for n in c.values()),'duplicate extra rows',sum(n-1 for n in c.values()))
print('known employees',sum(r['employee_id'] in E for r in R),'unknown',sum(r['employee_id'] not in E for r in R))
valid=[];seen=set();invalid=0;dups=0;unknown=0
for r in R:
 if r['employee_id'] not in E:unknown+=1;continue
 try:d=dt.date.fromisoformat(r['date'])
 except:invalid+=1;continue
 key=tuple((k,v) for k,v in r.items() if k!='id')
 if key in seen:dups+=1;continue
 seen.add(key);valid.append(r)
print('after exclusions',len(valid),'invalid',invalid,'dups',dups,'unknown',unknown)
print('\nCUMULATIVE PAY ERRORS')
for p,e in E.items():
 rows=sorted([r for r in valid if r['employee_id']==p],key=lambda r:r['date'])
 last_key=None;cum=0
 for r in rows:
  d=dt.date.fromisoformat(r['date']);start=d.replace(day=1);start+=dt.timedelta(days=(1-start.weekday())%7)
  bill=d.replace(day=1)
  if d<start:bill=(bill-dt.timedelta(days=1)).replace(day=1)
  if bill!=last_key:cum=0;last_key=bill
  cum+=float(r['hours_worked'])*float(e['hourly_rate'])
  if cum!=float(r['salary_amount']):print(p,r,'computed',cum,'billingmonth',str(bill))
print('\nZERO HOUR ROWS')
for r in valid:
 if r['hours_worked']=='0': print(r)
print('\nOTHER BONUS ERRORS WITH ONLY VALID TASKS')
for r in valid:
 tasks=[int(x) for x in re.findall(r'\d+',r['performed_tasks'])]
 if all(t in T for t in tasks):
  total=sum(T[t] for t in tasks)
  if total!=float(r['bonus']):print(r,'expected',total)
print('\nDUPLICATE EMPLOYEE/DAYS AFTER EXCLUSIONS')
c=collections.Counter((r['employee_id'],r['date']) for r in valid)
for k,n in c.items():
 if n>1:
  print(k,n)
  for r in valid:
   if (r['employee_id'],r['date'])==k:print(r)
print('\nPERIODS')
for p,e in E.items():
 out=collections.defaultdict(lambda:[0,0,0,0])
 for r in valid:
  if r['employee_id']!=p:continue
  d=dt.date.fromisoformat(r['date']);start=d.replace(day=1);start+=dt.timedelta(days=(1-start.weekday())%7)
  bill=d.replace(day=1)
  if d<start:bill=(bill-dt.timedelta(days=1)).replace(day=1)
  bonus=sum(T.get(int(t),0) for t in re.findall(r'\d+',r['performed_tasks']))
  a=out[str(bill)];a[0]+=int(r['hours_worked']);a[1]+=bonus;a[2]+=float(r['bonus']);a[3]+=1
 print(p,dict(sorted(out.items())))
